import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 28 Five pounds too dear","description":"学习 条件句中的礼貌距离，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 28 Five pounds too dear","description":"学习 条件句中的礼貌距离，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 条件句中的礼貌距离，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","link":"/life/english/new-concept/book-3/unit-02/lesson-027"},"next":{"text":"第三册：培养技能 · Lesson 29 Funny or not?","link":"/life/english/new-concept/book-3/unit-02/lesson-029"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 27 Nothing to sell and nothing to buy","link":"/life/english/new-concept/book-3/unit-02/lesson-027"},"next":{"text":"第三册：培养技能 · Lesson 29 Funny or not?","link":"/life/english/new-concept/book-3/unit-02/lesson-029"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-028.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-028.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-028.md"};function l(r,e,s,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-28-five-pounds-too-dear" tabindex="-1">第三册：培养技能 · Lesson 28 Five pounds too dear <a class="header-anchor" href="#第三册-培养技能-·-lesson-28-five-pounds-too-dear" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 28 Five pounds too dear&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕讨价还价和价值判断练习比较价格、做条件交换。价格低并不自动等于划算，还要考虑状态和用途。学习条件句中的真实可能与礼貌试探，把可接受的成交条件说明白，并避免将商业对话中的委婉语气误读成过去事件。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>bargain</td><td>/ˈbɑːɡən/</td><td>n.</td><td>便宜货或协议</td><td>a genuine bargain</td></tr><tr><td>quote</td><td>/kwəʊt/</td><td>v.</td><td>报价</td><td>quote a price</td></tr><tr><td>condition</td><td>/kənˈdɪʃən/</td><td>n.</td><td>状态</td><td>check the condition</td></tr><tr><td>reduce</td><td>/rɪˈdjuːs/</td><td>v.</td><td>降低</td><td>reduce the price</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>knock off — 从价格中减去某金额</li><li>walk away — 离开交易或谈判，不接受条件</li></ul><h2 id="语法讲解-条件句中的礼貌距离" tabindex="-1">语法讲解：条件句中的礼貌距离 <a class="header-anchor" href="#语法讲解-条件句中的礼貌距离" aria-label="Permalink to &quot;语法讲解：条件句中的礼貌距离&quot;">​</a></h2><p>If you reduce the price, I will buy it 说明可实现的条件与结果；If you reduced the price, I would consider it 使用过去式和 would，使提议更试探、更有距离，未必意味着现实绝无可能。could 常用于询问能否采取行动，也可软化请求。条件句的时态选择体现说话人如何看待情境，而不只是时间先后。谈判时应区分承诺 buy 与保留态度 consider，不能在转述中把“考虑购买”擅自改成“保证购买”。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>If you included the carrying case, I would consider paying the full price.</p></blockquote><p>如果您把便携盒也包括在内，我会考虑支付全价。</p><p>included 与 would consider 构成试探性条件；consider 不等于作出购买承诺。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I would consider to buy 应为 consider buying；consider 后接动名词，不能直接接 to do 表示考虑做某事。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 could you 与 would consider，保留礼貌助动词的声音；在 repaired 和 ten pounds less 上落重音，突出交易条件。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The handle is loose, although the case looks clean. If you repaired it, I would pay the listed price. Otherwise, I could offer ten pounds less.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句二手物品议价，说明检查结果、条件和可接受方案。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>让步句承认优点，条件句明确修理要求，otherwise 引出另一方案。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句承诺一定支付全价吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> would consider 只是会考虑。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：Could you ___ the price slightly?（reduce/reduced）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> reduce</p><p><strong>解析：</strong> 情态动词后接原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将“考虑购买”译为动词短语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> consider buying</p><p><strong>解析：</strong> consider 后用动名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：条件句中的礼貌距离。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-027">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-029">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
